import { Component, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { MeasurementType, CompareRequest, UNITS } from '../../../../core/models/measurement.models';

@Component({
  selector: 'app-compare-panel',
  templateUrl: './compare-panel.component.html'
})
export class ComparePanelComponent implements OnChanges {

  @Input() currentType: MeasurementType = 'Length';
  @Input() isLoading = false;
  @Output() execute = new EventEmitter<CompareRequest>();

  units: string[] = [];
  value1 = 1;
  value2 = 1000;
  unit1 = '';
  unit2 = '';

  // ngOnChanges fires whenever an @Input changes (e.g. user picks a new type)
  ngOnChanges(): void {
    this.units = UNITS[this.currentType];
    this.unit1 = this.units[0];
    this.unit2 = this.units[1] || this.units[0];
  }

  onCalculate(): void {
    this.execute.emit({
      category: this.currentType,
      value1: this.value1,
      unit1:  this.unit1,
      value2: this.value2,
      unit2:  this.unit2
    });
  }
}
<div class="input-panel active">
  <div class="compare-grid">

    <!-- Value 1 -->
    <div class="input-group">
      <div class="section-label">From</div>
      <!-- [(ngModel)] is two-way binding: updates value1 as the user types -->
      <input class="value-input" type="number" [(ngModel)]="value1" step="any"/>
      <select class="unit-select" [(ngModel)]="unit1">
        <option *ngFor="let u of units" [value]="u">{{ u }}</option>
      </select>
    </div>

    <!-- Value 2 -->
    <div class="input-group">
      <div class="section-label">To</div>
      <input class="value-input" type="number" [(ngModel)]="value2" step="any"/>
      <select class="unit-select" [(ngModel)]="unit2">
        <option *ngFor="let u of units" [value]="u">{{ u }}</option>
      </select>
    </div>

  </div>

  <!-- Execute button lives here so each panel controls its own button -->
  <div class="execute-row" style="margin-top:20px">
    <button class="btn-execute" [class.loading]="isLoading" (click)="onCalculate()">
      <div class="spinner"></div>
      <span class="btn-text">{{ isLoading ? 'Calculating...' : 'Calculate' }}</span>
    </button>
  </div>
</div>
